  if (request.isLive === true) return { ok: false, code: 'LIVE_EDGE_UNSUPPORTED' };
  if (request.format != null && !RENDERER_BOUNDARY_FORMATS.has(request.format)) {
    return { ok: false, code: 'UNSUPPORTED_RENDERER_FORMAT' };
