    return () => window.removeEventListener('player:cycle-playback-rate', onCycle);
  }, [setOwnerPlaybackRate]);

  const {
    targetTimeSeconds,
    setTargetTimeSeconds,
    consumeTargetTimeSeconds
  } = usePlaybackSession({ sessionKey: itemSessionKey, defaults: { targetTimeSeconds: explicitStartSeconds } });

  const handleResolvedMeta = useCallback((meta) => {
    if (!meta) {
      return;
    }
    setResolvedMeta(meta);
  }, []);

  // --- Subtitles and audio language (RQ-STEER-14) ---------------------------
  // Opt-in: everything below is inert unless an owner claims this Player
  // (lib/trackPolicy.js). With no owner the resolver returns the item as is.
  const appliedTracksRef = useRef(null); // { contentId, applied }
  const resolvedMetaRef = useRef(null);
  resolvedMetaRef.current = resolvedMeta;
