/**
 * The states a session can be settled by hand FROM: it came back, and marking
 * or closing never finished. Everything earlier belongs to the stuck-session
 * panel's Abandon, which is exactly the complement `MarkSessionAbandoned`
 * refuses — so the two surfaces never both offer a move, and never both
 * withhold one.
 */
const SETTLEABLE_STATES = new Set(['submitted', 'graded', 'outcome_recorded']);

/**
 * The use-case outcomes each half of a settle may report and still be finished.
 * Read as an ALLOW-list, not a deny-list: `awaiting_review` comes back 200 and
 * `ok`, but it means questions are still waiting on a person — closing after
 * one would report "that work has not been marked yet" and blame the wrong
 * half. Anything not named here stops the sequence.
 */
const MARKED_OUTCOMES = new Set(['graded', 'duplicate']);
const SETTLED_OUTCOMES = new Set(['settled', 'already_settled']);

/** What a use case said about itself, preferred over any generic HTTP text. */
const saidBy = (response, fallback) => {
  if (typeof response?.data?.message === 'string' && response.data.message) return response.data.message;
  if (typeof response?.data?.error === 'string' && response.data.error) return response.data.error;
  return fallback;
};

/**
 * Settle this by hand — the way out for a session that came back but never
 * finished marking: a scan that produced no attempts, a paper lesson somebody
 * marked off-screen, every question voided as unmarkable. `abandoned` is not
 * legal from any of those states, so the stuck-session panel links here rather
 * than offering a verb the server would refuse.
 *
 * THREE WRITES, ONE ACT:
 *
 *  1. `graded`, flagged `settle` so it costs a session-scoped step-up. A
 *     hand-settle carries no verdicts and would otherwise meet no gate at all.
 *  2. The reason, as a teacher note. It is the only half the CHILD ever reads
 *     — `RecordTeacherNote` puts it on the agenda's "Notes for you" and the
 *     student panel.
 *  3. `outcome_recorded`. Grading and stopping there would have moved the
 *     problem rather than solved it — the session would sit at `graded`, still
 *     open, still on the stuck list.
 *
 * WHY THE NOTE IS SECOND, not first. The instinct is to put the why on record
 * before anything moves. But the write that acts on this child is the GRADE,
 * and the grade can refuse — an all-voided sheet, a session still waiting on a
 * person. Note-first meant the child read a sentence about a settlement that
 * then did not happen, while the work stayed at `submitted`: a false sentence
 * to a child, which this house forbids more strongly than it demands
 * earliness. Second still puts it ahead of everything the principle protects —
 * ahead of `outcome_recorded`, ahead of the printed receipt, ahead of anything
 * that reaches their day.
 *
 * `duplicate` and `already_settled` are SUCCESS here: they say the half in
 * question was already on record, which is the state this form is trying to
 * reach. Anything else stops the sequence and is reported as what it is. A
 * settle that got partway is never announced as a settle.
 */
function SettleByHand({ sessionId, learnerId, learnerName, currentPercent, onSettled }) {
  const [reason, setReason] = useState('');
  const [preview, setPreview] = useState(false);
  // Whether this SESSION's note is already on record — keyed to the session id,
  // never to the reason text. `useTeacherWrite` replays a 403'd call once after
  // re-authorizing, and a teacher stuck at a refusing grade half will reword
  // and try again; both must send the child one note, not two.
  const deliveredRef = useRef(null);
  const { run, busy, errors } = useTeacherWrite({ panel: 'session-settle' });
  const key = `settle:${sessionId}`;
  const alreadyMarked = typeof currentPercent === 'number';
  const valid = Boolean(reason.trim());

  const settle = () => run(key, async ({ actorId, pin, stepUpToken }) => {
    const graded = await schoolApi.gradeSession(sessionId, {
      gradedBy: actorId, pin, settle: true, settledBy: actorId,
    }, stepUpToken);
    if (!MARKED_OUTCOMES.has(graded.data?.status)) {
      // Nothing was written and nothing was said: a refused grade means no
      // decision was taken about this child, so there is nothing to tell them.
      // A 403 is the one refusal `useTeacherWrite` can act on (it re-prompts
      // and replays), so it travels unrewritten; everything else reports the
      // use case's own sentence about why.
      if (graded.status === 403) return graded;
      return { ok: false, status: graded.status, data: { error:
        `Nothing was changed — the marking didn’t go through: ${saidBy(graded, 'that work could not be marked')}` } };
    }
    if (deliveredRef.current !== sessionId) {
      const delivered = await schoolApi.postTeacherNote({
        learnerId, note: reason.trim(), from: actorId, pin,
      });
      if (!delivered.ok) return delivered;
      deliveredRef.current = sessionId;
    }
    const closed = await schoolApi.closeSession(sessionId, { pin });
    if (!SETTLED_OUTCOMES.has(closed.data?.status)) {
      return { ok: false, status: closed.status, data: { error:
        `It is marked, but closing it out didn’t go through: ${saidBy(closed, 'the close was refused')}. Settle it again to finish.` } };
    }
    return { ok: true, status: closed.status, data: closed.data };
  }, {
    stepUp: { action: 'sessions.settle', resource: sessionId },
    onSuccess: () => { setPreview(false); setReason(''); deliveredRef.current = null; onSettled?.(); },
  });

  return (
    <section className="teacher-panel teacher-session-settle">
      <h3 className="teacher-panel__title">Settle this by hand</h3>
      <p>This lesson came back but never finished marking. Record what it earned and close it out.</p>
      <label>Reason <input aria-label="Settlement reason" maxLength="240"
        placeholder={`What happened? ${learnerName} will see this.`}
        value={reason} onChange={(event) => { setReason(event.target.value); setPreview(false); }} /></label>
      {preview && (
        <div className="teacher-action-preview">
          <strong>Settling does three things</strong>
          <ol>
            <li>{alreadyMarked
              ? `The ${Math.round(currentPercent)}% already on record stands.`
              : 'The mark is finished from the answers already on record.'}</li>
            <li>{learnerName} gets your note: “{reason.trim()}”</li>
            <li>The result is recorded and a receipt goes to the printer.</li>
          </ol>
        </div>
      )}
      <div className="teacher-action-row">
        {!preview && <button type="button" disabled={!valid || busy === key}
          onClick={() => setPreview(true)}>Preview settlement</button>}
        {preview && <button type="button" disabled={!valid || busy === key} onClick={settle}>Settle it</button>}
        {preview && <button type="button" onClick={() => setPreview(false)}>Cancel</button>}
      </div>
      {errors[key] && <p className="teacher-panel__error">{errors[key]}</p>}
    </section>
  );
}

function ArtifactReprint({ artifactId, kind = 'worksheet', onPrinted }) {
  const [preview, setPreview] = useState(null);
  const [idempotencyKey, setIdempotencyKey] = useState(null);
  const { run, busy, errors } = useTeacherWrite({ panel: 'artifact-reprint' });
  const key = `reprint:${artifactId}`;
  const prepare = () => {
    const requestKey = newIdempotencyKey(key); setIdempotencyKey(requestKey);
    run(key, ({ actorId, pin }) => teacherWorkspaceApi.reprintArtifact(artifactId,
      { reprintedBy: actorId, pin, apply: false }, requestKey), { onSuccess: setPreview });
  };
  // `artifact.reprint` is ReprintIssuedArtifact's audit label, not a step-up
  // grant name — the capability cookie is the whole authority the reprint route
  // checks. Requesting a grant here hung the button on an unsatisfiable dialog.
  const print = () => run(key, ({ actorId, pin }) => teacherWorkspaceApi.reprintArtifact(artifactId,
    { reprintedBy: actorId, pin, apply: true }, idempotencyKey), {
    onSuccess: () => { setPreview(null); setIdempotencyKey(null); onPrinted?.(); },
  });
  const label = kind === 'result-receipt' || kind === 'result-correction' ? 'Result receipt' : 'Worksheet';
  return <>{!preview ? <button type="button" disabled={busy === key} onClick={prepare}>Print another copy…</button> : <span className="teacher-reprint-confirm"><span>{label} ready to print</span><button type="button" disabled={busy === key} onClick={print}>Print now</button><button type="button" onClick={() => { setPreview(null); setIdempotencyKey(null); }}>Cancel</button></span>}{errors[key] && <span className="teacher-panel__error">{errors[key]}</span>}</>;
}

export function SessionInspector({ learnerId, sessionId, kids, onBack, backLabel = 'Back' }) {
  const [result, setResult] = useState({ state: 'loading', session: null, ownerId: learnerId });
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    let alive = true;
    const load = async () => {
      // Reaching the teacher surface is the read boundary for now. History
      // must not be blocked by the future login wrapper or make a user claim
      // just to see an already-issued session.
      const dedicated = await teacherWorkspaceApi.session(sessionId);
      if (dedicated.ok) return { state: 'ok', session: dedicated.data, ownerId: dedicated.data?.state?.learnerId ?? dedicated.data?.learnerId ?? learnerId };
      if (dedicated.status !== 404) return { state: 'error', session: null, ownerId: learnerId };
      const candidates = learnerId ? kids.filter((kid) => kid.id === learnerId) : kids;
      const rows = await Promise.all(candidates.map(async (kid) => ({ kid, response: await schoolApi.learnerSessions(kid.id) })));
      for (const { kid, response } of rows) {
        const session = (response.data?.sessions ?? []).find((item) => sessionIdOf(item) === sessionId);
        if (session) return { state: 'ok', session, ownerId: kid.id };
      }
      const unavailable = rows.length && rows.every(({ response }) => response.status === 404);
      return { state: unavailable ? 'unavailable' : 'empty', session: null, ownerId: learnerId };
    };
    load().then((next) => {
      if (!alive) return;
      setResult(next);
    }).catch(() => alive && setResult({ state: 'error', session: null, ownerId: learnerId }));
    return () => { alive = false; };
  }, [learnerId, sessionId, kids, attempt]);

  const session = result.session;
  const sessionState = session?.schema?.startsWith('school.teacher-session/') ? session.state : session;
  const machineGrade = session?.scores?.machine?.percent ?? sessionState?.machineGrade?.percent ?? sessionState?.gradedPercent ?? sessionState?.percent ?? null;
  const effectiveGrade = session?.scores?.effective?.percent ?? sessionState?.effectiveGrade?.percent ?? sessionState?.gradedPercent ?? sessionState?.percent ?? null;
  const gradeAdjustments = sessionState?.gradeAdjustments ?? [];
  const presentation = presentSessionState(sessionState);
  const capabilities = session?.capabilities ?? {};
  // OFFERED ONLY WHILE THE SERVER CAN HONOUR IT — once, and never again.
  //
  // `OpenRemediation` returns `already_opened` for any session that has one,
  // live or abandoned (`OpenRemediation.mjs:57-66`), and the route answers it
  // at HTTP 201 — which `useTeacherWrite` reads as a save. A button offered
  // past this point reports success, creates nothing, and tells a parent a
  // fresh sheet is waiting when the only sheet is a dead one.
  //
  // A retake that is abandoned or never scanned therefore strands the parent
  // session at `remediation_opened` with no second try available. That gap is
  // real and is filed as a known residual (audit A10, `teacher.md` §16): the
  // domain has no edge out of `remediation_opened` — see `TRANSITIONS` in
  // `sessionEvents.mjs`, which the datastore enforces on append — so closing
  // it means changing the transition table and deciding how `variant` cycles
  // across a second one. Neither is this component's call. Until then the
  // console does not offer a move the domain refuses.
  const canOfferRetake = capabilities.offerRetake
    ?? (sessionState?.outcome?.result === 'needs_remediation' && !sessionState?.remediation);
  const canCorrectGrade = capabilities.gradeCorrection
    ?? Boolean(session?.scores?.machine ?? sessionState?.machineGrade);
  const canPreviewLaunch = capabilities.launchPreview
    ?? Boolean((session?.taxonomy?.subject ?? sessionState?.subject) && sessionState?.terminal !== true);
  const hasCompanionRecovery = capabilities.companionRecovery ?? false;
  // No learner, no settle: the reason is delivered TO a child by name, and a
  // form that cannot name one would write a note nobody receives.
  const settleLearnerId = result.ownerId ?? learnerId ?? null;
  const canSettleByHand = Boolean(settleLearnerId) && (capabilities.manualSettlement
    ?? (SETTLEABLE_STATES.has(sessionState?.state) && sessionState?.terminal !== true));
  const { run, busy, errors } = useTeacherWrite({ panel: 'session-retake' });
  const offerRetake = () => run(sessionId, ({ actorId, pin }) => schoolApi.offerRetake(sessionId, {
    openedBy: actorId, pin,
  }), { onSuccess: () => setAttempt((n) => n + 1) });
  const ownerName = kids.find((kid) => kid.id === result.ownerId)?.name ?? result.ownerId;
  const events = useMemo(() => session?.events ?? sessionState?.events ?? sessionState?.history ?? [], [session, sessionState]);
  const updatedAt = dateOf(session) ?? session?.updatedAt ?? events.at(-1)?.at ?? null;
  const previewSubject = session?.taxonomy?.subject ?? sessionState?.subject ?? null;

  return (
    <div className="teacher-view teacher-session-inspector">
      <button type="button" className="teacher-back" onClick={onBack}>← {backLabel}</button>
      <div className="teacher-session-heading"><LessonIdentity subject={session?.taxonomy?.subject} courseTitle={session?.taxonomy?.courseTitle} moduleTitle={session?.taxonomy?.moduleTitle} lessonTitle={session?.taxonomy?.lessonTitle ?? sessionState?.title} posterUrl={session?.taxonomy?.posterUrl} heading /><p>{ownerName ? `${ownerName}’s lesson record` : ''}</p></div>
      {result.state === 'loading' && <div className="teacher-panel__skeleton" aria-label="Loading session" />}
      {result.state === 'error' && <p className="teacher-panel__error">Couldn’t load this session. <button type="button" onClick={() => setAttempt((n) => n + 1)}>Retry</button></p>}
      {result.state === 'empty' && <CapabilityNotice>This session is not present in the available learner-history window. A dedicated session read endpoint is required to inspect older records.</CapabilityNotice>}
      {result.state === 'unavailable' && <CapabilityNotice>Session inspection is not enabled on this install.</CapabilityNotice>}
      {session && (
        <>
          <section className={`teacher-panel teacher-session-summary teacher-session-summary--${presentation.tone}`}>
            <h3 className="teacher-panel__title">Status</h3>
            <div className="teacher-session-status">
              <span className={`teacher-session-status__label is-${presentation.tone}`}>{presentation.label}</span>
              <p>{presentation.description}</p>
              <div className="teacher-session-status__facts">
                {typeof effectiveGrade === 'number' && <span><small>Score</small><strong>{Math.round(effectiveGrade)}%</strong>
                  {typeof machineGrade === 'number' && Math.round(machineGrade) !== Math.round(effectiveGrade)
                    && <em>corrected from {Math.round(machineGrade)}%</em>}</span>}
                {humanDateTime(updatedAt) && <span><small>Last activity</small><strong>{humanDateTime(updatedAt)}</strong></span>}
              </div>
            </div>
            {/* One button vocabulary (UX audit IA4/IA5): the repair you came
                here for is primary, the conditional retake is a peer, and the
                cross-page tool is navigation — not a back link, and not a
                noun-dash-noun label that reads as a form caption. */}
            <div className="teacher-action-row">
              {canPreviewLaunch && <LaunchPreviewAction learnerId={settleLearnerId} subject={previewSubject} />}
              {canCorrectGrade && <GradeCorrection sessionId={sessionId} revision={session?.revision} currentPercent={effectiveGrade}
                items={session?.reviewEvidence ?? []} onApplied={() => setAttempt((n) => n + 1)} />}
              {canOfferRetake && <button type="button" className="teacher-btn" disabled={busy === sessionId}
                onClick={offerRetake}>Offer another try</button>}
            </div>
            <details className="teacher-session-more-actions">
              <summary>More actions</summary>
              <a href={`${teacherBaseFor(globalThis.location?.pathname ?? '')}/students/${encodeURIComponent(result.ownerId ?? learnerId ?? '')}/operations`}>
                Give credit for work completed offline →
              </a>
            </details>
            {errors[sessionId] && <p className="teacher-panel__error">{errors[sessionId]}</p>}
          </section>
          {/* Below the repair a teacher came for, never above it: settling
              stuck bookkeeping is the exception path. Shown only where it
              means anything — a session that came back and has not finished.
              Earlier states are abandoned, not settled, and the stuck-session
              panel routes those elsewhere; a terminal one is already done.
              Nothing at all rather than a disabled button (UX audit IA4). */}
          {canSettleByHand && (
            <SettleByHand sessionId={sessionId} learnerId={settleLearnerId}
              learnerName={ownerName} currentPercent={effectiveGrade}
              onSettled={() => setAttempt((n) => n + 1)} />
          )}
          {/* The escape hatch for a required read-along that will not play.
              The read model exposes the capability only for lessons whose
              companion is required, so unrelated sessions do not advertise
              a recovery tool that cannot help them. It shows nothing until
              the teacher opens the fold. */}
          {hasCompanionRecovery && (
            <details className="teacher-panel teacher-fold teacher-troubleshoot">
              <summary><h3 className="teacher-panel__title">Troubleshoot this lesson</h3><span>Read-along recovery</span></summary>
              <CompanionFinishCode sessionId={sessionId} embedded />
            </details>
          )}
          {(session?.assignment || session?.assessment?.items?.length > 0) && (
            <section className="teacher-panel">
              <h3 className="teacher-panel__title">Questions and answers</h3>
              {session.assignment?.createdAt && (
                <p className="teacher-muted">Worksheet issued {humanDateTime(session.assignment.createdAt) ?? 'at session start'}.</p>
              )}
              <GradedWorksheet assignment={session.assignment} assessment={session.assessment} />
            </section>
          )}
          {session?.answerSheets?.length > 0 && (
            <details className="teacher-panel teacher-fold">
              <summary><h3 className="teacher-panel__title">Answer card</h3><span>Bubble-sheet capacity and mapping</span></summary>
              {session.answerSheets.map((card) => <dl className="teacher-answer-sheet" key={card.cardId}><div><dt>Student No.</dt><dd>{card.studentNumber}</dd></div><div><dt>Mapped learner</dt><dd>{card.mappedLearnerId ?? 'Unmapped'}</dd></div><div><dt>Capacity</dt><dd>{card.usedRows} of {card.capacity} rows used</dd></div><div><dt>Remaining</dt><dd>{card.remainingContiguousSlots} contiguous slots · next row {card.nextRow ?? 'full'}</dd></div>{card.warnings?.map((warning) => <p role="alert" key={warning}>{warning}</p>)}</dl>)}
            </details>
          )}
          {session?.artifacts?.length > 0 && <section className="teacher-panel teacher-session-materials">
            <h3 className="teacher-panel__title">Issued materials and results</h3>
            <p className="teacher-muted">These are the paper records from this lesson.</p>
            <div className="teacher-session-materials__cards">{session.artifacts.map((artifact) => (
              <IssuedArtifactCard
                key={artifact.artifactId}
                artifact={artifact}
                lessonTitle={session.taxonomy?.lessonTitle ?? session.assignment?.title ?? 'Lesson'}
                action={['exact', 'regenerable'].includes(artifact.availability)
                  ? <ArtifactReprint artifactId={artifact.artifactId} kind={artifact.kind} onPrinted={() => setAttempt((n) => n + 1)} />
                  : null}
              />
            ))}</div>
          </section>}
          {gradeAdjustments.length > 0 && <section className="teacher-panel"><h3 className="teacher-panel__title">Grade corrections</h3><ol className="teacher-event-list">{gradeAdjustments.map((adjustment) => <li key={adjustment.adjustmentId}><strong>{adjustment.percent == null ? 'Evidence correction' : `${adjustment.percent}% correction`}</strong><span>{adjustment.reason}</span><small>{adjustment.adjustedBy}{adjustment.at ? ` · ${humanDateTime(adjustment.at)}` : ''}</small><GradeAdjustmentRetraction sessionId={sessionId} adjustment={adjustment} revision={session.revision} onApplied={() => setAttempt((n) => n + 1)} /></li>)}</ol></section>}
          <details className="teacher-panel teacher-fold">
            <summary><h3 className="teacher-panel__title">Activity history</h3><span>{events.length} recorded step{events.length === 1 ? '' : 's'}</span></summary>
            {events.length ? <ol className="teacher-event-list">{events.map((event, index) => <li key={event.id ?? `${event.type}:${index}`}><strong>{labelize(event.type ?? event.kind)}</strong><span>{humanDateTime(event.at) ?? ''}</span><small>{event.by ?? event.actorId ?? event.gradedBy ?? ''}</small></li>)}</ol> : <p className="teacher-panel__empty">Detailed lifecycle events require the session-detail read model.</p>}
          </details>
        </>
      )}
    </div>
  );
}

modules/school/browser/teacher/TeacherCo.bytes:
/**
 * TeacherConsole — a route-driven adult operations workspace.
 *
 * The shell keeps household triage and learner context persistent on a desk,
 * while the same information architecture becomes ordinary stacked screens
 * on a phone. Business actions remain in the existing panels and all writes
 * continue through useTeacherWrite/TeacherGate.
 */
import { useCallback, useEffect, useMemo, useState } from 'react';
import ProfilePicker from "../../../../frontend/src/lib/identity/ProfilePicker.jsx";
import ProfileAvatar from "../../../../frontend/src/lib/identity/ProfileAvatar.jsx";
import PinPrompt from "./panels/PinPrompt.jsx";
import { TeacherProfileProvider, useTeacherProfile } from "./TeacherProfileContext.jsx";
import { schoolApi } from "../schoolApi.js";
import { teacherLog } from "./teacherLog.js";
import {
  parseTeacherPath, teacherDayPath, teacherLearnerPath, teacherSectionPath, teacherSessionPath,
} from "./teacherUrl.js";
import { humanDate, localDay } from "./teacherDates.js";
import TabErrorBoundary from "./TabErrorBoundary.jsx";
import {
  CoursesView, CurriculumView, DashboardView, HistoryView, LearnerDayScreen, LearnerOperationsView,
  OperationsView, QueueView, ReadingView, ReportsView, SessionInspector, WordsView, CoinsView, CoinsRosterView,
} from "./WorkspaceViews.jsx";
import "./Teacher.scss";

// `short` is the phone tab label — a truthful abbreviation of the SAME word,
// never a different one ('Courses' for Curriculum collided with the student
// Courses tab; UX audit F26).
const GLOBAL_NAV = [
  { id: 'dashboard', label: 'Dashboard', short: 'Home' },
  { id: 'queue', label: 'Action queue', short: 'Queue' },
  { id: 'curriculum', label: 'Curriculum', short: 'Curric.' },
  { id: 'coins', label: 'Coins', short: 'Coins' },
  { id: 'operations', label: 'Operations', short: 'Ops' },
];
const LEARNER_NAV = [
  { id: 'day', label: 'Day' },
  { id: 'courses', label: 'Courses' },
  { id: 'history', label: 'History' },
  { id: 'reading', label: 'Reading' },
  { id: 'words', label: 'Cards' }, // id kept: console links name the tab `words`
  { id: 'coins', label: 'Coins' },
  { id: 'reports', label: 'Reports' },
  { id: 'operations', label: 'Operations' },
];

function TeacherShell() {
  const {
    status, configured, teachers, currentTeacher, claim, release, authorization,
    pickerOpen, openPicker, closePicker,
  } = useTeacherProfile();
  const initial = useMemo(() => parseTeacherPath(window.location.pathname), []);
  const [route, setRoute] = useState(initial);
  const [kids, setKids] = useState([]);
  const [backlog, setBacklog] = useState(0);
  const [shellWarnings, setShellWarnings] = useState({ roster: false, backlog: false });
  const [railOpen, setRailOpen] = useState(false);

  const navigate = useCallback((path, replace = false) => {
    if (`${window.location.pathname}${window.location.search}` !== path) window.history[replace ? 'replaceState' : 'pushState']({}, '', path);
    const next = parseTeacherPath(new URL(path, window.location.origin).pathname);
    setRoute(next);
    setRailOpen(false);
    teacherLog.nav('workspace', { kind: next.kind, section: next.section, learnerId: next.learnerId, sessionId: next.sessionId });
  }, []);

  useEffect(() => {
    teacherLog.nav('mounted', { kind: initial.kind, section: initial.section, learnerId: initial.learnerId });
    let alive = true;
    schoolApi.roster().then(({ ok, data }) => {
      if (!alive) return;
      if (ok && Array.isArray(data)) {
        setKids(data);
        setShellWarnings((value) => ({ ...value, roster: false }));
      } else {
        setShellWarnings((value) => ({ ...value, roster: true }));
        teacherLog.fetch('roster-failed', { status: ok ? 200 : 'unavailable' });
      }
    });
    return () => { alive = false; };
  }, [initial]);

  useEffect(() => {
    let alive = true;
    const poll = async () => {
      // A hidden tab polls nothing; visibilitychange below catches up on return.
      if (document.visibilityState === 'hidden') return;
      const [review, prints] = await Promise.all([schoolApi.lifecycleReview(), schoolApi.printPending()]);
      if (!alive) return;
      setBacklog((review.ok ? (review.data?.items ?? []).length : 0) + (prints.ok && Array.isArray(prints.data) ? prints.data.length : 0));
      const failed = !review.ok || !prints.ok;
      setShellWarnings((value) => ({ ...value, backlog: failed }));
      if (failed) teacherLog.fetch('backlog-failed', { reviewStatus: review.status, printStatus: prints.status });
    };
    poll();
    const timer = setInterval(poll, 60_000);
    const onVisible = () => { if (document.visibilityState === 'visible') poll(); };
    document.addEventListener('visibilitychange', onVisible);
    return () => { alive = false; clearInterval(timer); document.removeEventListener('visibilitychange', onVisible); };
  }, []);

  useEffect(() => {
    const onPop = () => setRoute(parseTeacherPath(window.location.pathname));
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, []);

  useEffect(() => {
    // `/students/:id/overview` is a retired alias of the Day record (trim
    // 5.6) — canonicalize the bookmark to the bare learner path (the Day
    // record) instead of rendering a second view at the old URL.
    if (route.kind === 'learner' && route.section === 'overview' && route.learnerId) {
      navigate(`${route.base}/students/${encodeURIComponent(route.learnerId)}`, true);
    }
  }, [route, navigate]);

  const learner = kids.find((kid) => kid.id === route.learnerId) ?? null;
  const goGlobal = (section) => navigate(teacherSectionPath(section, route.base));
  const goLearner = (learnerId, section = 'day', detail = null) => navigate(teacherLearnerPath(learnerId, section, detail, route.base));
  const goSession = (sessionId, origin = {}) => navigate(teacherSessionPath(route.learnerId, sessionId, route.base, origin));
  const studyDay = route.studyDay ?? localDay();
  const goDay = (nextDay) => navigate(teacherDayPath(route.learnerId, nextDay, route.base));

  if (status !== 'ready') return <div className="teacher-console-page"><div className="teacher-console teacher-console--loading">Loading teacher workspace…</div></div>;

  const noTeachers = !configured || teachers.length === 0;
  let view;
  if (route.kind === 'not-found') {
    view = <section className="teacher-panel"><h2 className="teacher-panel__title">Page not found</h2><p className="teacher-panel__empty">This teacher-workspace address is not a valid route.</p><button type="button" onClick={() => goGlobal('dashboard')}>Return to dashboard</button></section>;
  } else if (route.kind === 'session') {
    // Back returns to the view that opened the session (?from=today → the
    // dashboard digest), not always History.
    const origin = new URLSearchParams(window.location.search);
    const from = origin.get('from');
    const originDay = origin.get('studyDay');
    const backToDay = from === 'day' && /^\d{4}-\d{2}-\d{2}$/.test(originDay ?? '');
    const backLabel = backToDay ? `Back to ${humanDate(originDay)}`
      : from === 'today' || !route.learnerId ? 'Back to dashboard' : 'Back to history';
    view = <SessionInspector learnerId={route.learnerId} sessionId={route.sessionId} kids={kids}
      backLabel={backLabel}
      onBack={() => (backToDay ? goDay(originDay)
        : (from === 'today' || !route.learnerId ? goGlobal('dashboard') : goLearner(route.learnerId, 'history')))} />;
  } else if (route.kind === 'learner' && learner) {
    const views = {
      day: <LearnerDayScreen learnerId={learner.id} learnerName={learner.name} studyDay={studyDay}
        onChangeStudyDay={goDay} onOpenSession={(sessionId) => goSession(sessionId, { from: 'day', studyDay })} />,
      courses: <CoursesView learnerId={learner.id} learnerName={learner.name} courseId={route.courseId} kids={kids} />,
      history: <HistoryView learnerId={learner.id} learnerName={learner.name}
        onOpenSession={(sessionId) => goSession(sessionId, { from: 'history' })} />,
      reading: <ReadingView learnerId={learner.id} learnerName={learner.name} kids={kids} />,
      words: <WordsView learnerId={learner.id} learnerName={learner.name} />,
      coins: <CoinsView learnerId={learner.id} learnerName={learner.name} />,
      reports: <ReportsView learnerId={learner.id} kids={kids} />,
      operations: <LearnerOperationsView learnerId={learner.id} learnerName={learner.name} kids={kids} />,
    };
    view = views[route.section] ?? views.day;
  } else {
    const views = {
      dashboard: <DashboardView kids={kids} onSelectLearner={(id) => goLearner(id)} onOpenQueue={() => goGlobal('queue')} />,
      queue: <QueueView kids={kids} />,
      curriculum: <CurriculumView kids={kids} courseId={route.courseId} lessonId={route.lessonId} />,
      coins: <CoinsRosterView onSelectLearner={(id) => goLearner(id, 'coins')} />,
      operations: <OperationsView kids={kids} />,
    };
    view = views[route.section] ?? views.dashboard;
  }

  return (
    /* Grown-up admin: dates, bank ids, reasons. Never Hangul. */
    <div className="teacher-console-page" data-ime="off">
      <div className="teacher-console teacher-workspace">
        <header className="teacher-console__header teacher-workspace__topbar">
          <button type="button" className="teacher-workspace__menu" aria-label="Open navigation" aria-expanded={railOpen} onClick={() => setRailOpen((open) => !open)}>☰</button>
          <button type="button" className="teacher-workspace__brand" onClick={() => goGlobal('dashboard')}><span>School</span><strong>Teacher</strong></button>
          <div className="teacher-workspace__context" title={learner ? learner.name : GLOBAL_NAV.find((item) => item.id === route.section)?.label ?? 'Session'}>{learner ? learner.name : GLOBAL_NAV.find((item) => item.id === route.section)?.label ?? 'Session'}</div>
          {noTeachers ? (
            <div className="teacher-console__no-teachers">{configured ? 'Configured teachers do not resolve to the roster.' : 'No teachers configured in school.yml.'}</div>
          ) : (
            <div className="teacher-console__identity">
              <button type="button" className="teacher-console__chip" onClick={openPicker} title={authorization.active ? 'Teacher tools unlocked' : 'Choose teacher'}>
                {currentTeacher ? <><ProfileAvatar id={currentTeacher.id} name={currentTeacher.name} /><span>{currentTeacher.name}</span><i aria-label={authorization.active ? 'Unlocked' : 'Locked'}>{authorization.active ? '●' : '○'}</i></> : <span>Teacher tools</span>}
              </button>
              {currentTeacher && <button type="button" className="teacher-console__lock" onClick={release}>Lock</button>}
            </div>
          )}
        </header>

        <div className="teacher-workspace__layout">
          <aside className={`teacher-workspace__rail${railOpen ? ' is-open' : ''}`} aria-label="Teacher workspace navigation">
            <nav className="teacher-workspace__global" aria-label="Workspace">
              {GLOBAL_NAV.map((item) => (
                <button key={item.id} type="button" aria-current={route.kind === 'section' && route.section === item.id ? 'page' : undefined} onClick={() => goGlobal(item.id)}>
                  <span>{item.label}</span>{item.id === 'queue' && backlog > 0 && <b aria-label={`${backlog} items waiting`}>{backlog}</b>}
                </button>
              ))}
            </nav>
            <div className="teacher-workspace__rail-label">Students</div>
            <nav className="teacher-workspace__students" aria-label="Students">
              {kids.map((kid) => (
                <button key={kid.id} type="button" aria-current={kid.id === route.learnerId ? 'page' : undefined} onClick={() => goLearner(kid.id)}>
                  <ProfileAvatar id={kid.id} name={kid.name} /><span>{kid.name}</span>
                </button>
              ))}
            </nav>
          </aside>
          {railOpen && <button type="button" className="teacher-workspace__scrim" aria-label="Close navigation" onClick={() => setRailOpen(false)} />}

          <div className="teacher-workspace__main">
            {(shellWarnings.roster || shellWarnings.backlog) && (
              <div className="teacher-workspace__alerts" role="status">
                {shellWarnings.roster && <span>Student roster unavailable. Navigation may be incomplete.</span>}
                {shellWarnings.backlog && <span>Action-queue totals unavailable. Open the queue for item-level status.</span>}
              </div>
            )}
            {learner && route.kind !== 'session' && (
              <nav className="teacher-workspace__learner-nav" aria-label={`${learner.name} workspace`}>
                {LEARNER_NAV.map((item) => <button key={item.id} type="button" aria-current={route.section === item.id ? 'page' : undefined} onClick={() => goLearner(learner.id, item.id)}>{item.label}</button>)}
              </nav>
            )}
            <main className="teacher-console__body" id="teacher-main">
              {!learner && route.kind === 'learner' ? (
                <section className="teacher-panel"><h2 className="teacher-panel__title">Student not found</h2><p className="teacher-panel__empty">This bookmark names a learner who is no longer on the roster.</p><button type="button" onClick={() => goGlobal('dashboard')}>Return to dashboard</button></section>
              ) : (
                <TabErrorBoundary tab={route.section} resetKey={`${route.learnerId ?? ''}:${route.sessionId ?? ''}`}>{view}</TabErrorBoundary>
              )}
            </main>
          </div>
        </div>

        <nav className="teacher-workspace__mobile-nav" aria-label="Sections">
          {GLOBAL_NAV.map((item) => <button key={item.id} type="button" aria-label={item.label} aria-current={route.kind === 'section' && route.section === item.id ? 'page' : undefined} onClick={() => goGlobal(item.id)}>{item.short}{item.id === 'queue' && backlog > 0 && <b>{backlog}</b>}</button>)}
        </nav>
        <PinPrompt />
        <ProfilePicker open={pickerOpen} users={teachers} activeId={currentTeacher?.id} onPick={claim} onDismiss={closePicker} timeoutMs={600000} title="Who’s teaching?" />
      </div>
    </div>
  );
}

export default function TeacherConsole() {
  return <TeacherProfileProvider><TeacherShell /></TeacherProfileProvider>;
}

import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { MantineProvider } from '@mantine/core';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import TeacherConsoleView from "./TeacherConsole.jsx";

const TeacherConsole = () => <MantineProvider><TeacherConsoleView /></MantineProvider>;

vi.mock("../schoolApi.js", () => {
  const okEmpty = async () => ({ ok: true, status: 200, data: [] });
